:Equipment a owl:Class ;
  rdfs:label "设备"@zh .

:Alarm a owl:Class ;
  rdfs:label "告警"@zh .

:hasAlarm a owl:ObjectProperty ;
  rdfs:domain :Equipment ;
  rdfs:range :Alarm .

:equipment/001 :hasAlarm :alarm/A01 .

:equipment/001 a :Equipment ;
  :equipmentName "泵站A" ;
  :installDate "2024-01-15"^^xsd:date ;
  :enabled true .

:equipment/002 a :Equipment ;
  :equipmentName "泵站B" ;
  :installDate "2024-02-20"^^xsd:date ;
  :enabled true .

SELECT ?alarm ?equipment ?level ?status WHERE {
  ?alarm a :Alarm ;
    :alarmLevel ?level ;
    :alarmStatus ?status .
  ?equipment :hasAlarm ?alarm .
  FILTER(?level = "High" && ?status != "Closed")
} ORDER BY ?alarm

